functions.callGeminiAPI:
async function callGeminiAPI(prompt, systemInstruction) {
    try {
        const response = await fetch('/api/gemini', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ prompt: prompt, systemInstruction: systemInstruction })
        });
        const data = await response.json();
        if (!response.ok) return `連線錯誤：${data.error || '未知錯誤'}`;
        let rawText = data.candidates?.[0]?.content?.parts?.[0]?.text || "抱歉，無法產生有效回覆。";
        return rawText.replace(/\n/g, '<br>').replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');
    } catch (error) { return `網路連線失敗。(${error.message})`; }
}

functions.appendMessage:
function appendMessage(text, isUser) {
    const msgDiv = document.createElement('div');
    msgDiv.className = isUser ? 'bg-blue-100 text-blue-900 rounded-tr-none rounded-2xl ml-auto max-w-[85%] p-3 text-sm shadow-sm' : 'bg-white border border-slate-200 text-slate-700 rounded-tl-none rounded-2xl mr-auto max-w-[85%] p-3 text-sm shadow-sm leading-relaxed';
    // 🔒 安全：使用者訊息用 textContent 防注入；AI 回覆經 DOMPurify 消毒後僅允許 b/strong/em/br
    if (isUser) {
        msgDiv.textContent = text;
    } else {
        msgDiv.innerHTML = DOMPurify.sanitize(text, { ALLOWED_TAGS: ['b', 'strong', 'em', 'br'], ALLOWED_ATTR: [] });
    }
    const chatMessages = document.getElementById('chat-messages');
    chatMessages.appendChild(msgDiv);
    chatMessages.scrollTop = chatMessages.scrollHeight;
}

